using Intranet.Entity;
using Intranet.Service;
namespace Intranet.Api.Tests;
public sealed class AnalisisRbAutomaticSectorTests {
 private static AnalisisRbSave Request(bool complete=true){var request=new AnalisisRbSave{RequestId=Guid.NewGuid(),Source=new("J1825",217,1.404m,11.51m),UsedTime=complete?1.557m:.7m,ServicePrice=1,OtherExpenses=.03m,SectorAnalysis=new("99863","0","CO","CORTE",1.557m,9,complete?9:1,complete)};if(!complete)request.PartialSelection=new("99863","0","CO","CORTE",1.557m,[new("01","CORTE","001","OP1","0","CORTAR",.7m)]);return request;}
 [Fact]public void FullSectorIsCompleteWithoutSelectedProcessList(){var snapshot=AnalisisRbHistoryService.BuildSnapshot(Request(),DateTime.Today);Assert.Null(snapshot.PartialSelection);Assert.True(snapshot.SectorAnalysis!.IsComplete);Assert.Equal("TIEMPO COMPLETO",snapshot.Calculated.TimeLabel);Assert.Equal("CORTE COMPLETO",snapshot.Calculated.Observation);Assert.Equal(1.404m,snapshot.Calculated.CommercialTotal);Assert.Equal(0,snapshot.Calculated.RemovedTime);Assert.Equal(11.51m,snapshot.Source.SewingTime);Assert.Equal(1.557m,snapshot.SectorAnalysis.TotalTime);}
 [Fact]public void PartialUsesSelectedSectorAsDenominator(){var snapshot=AnalisisRbHistoryService.BuildSnapshot(Request(false),DateTime.Today);Assert.False(snapshot.SectorAnalysis!.IsComplete);Assert.Single(snapshot.PartialSelection!.Operations);Assert.Equal(.7m*1.404m/1.557m,snapshot.Calculated.CommercialTotal);Assert.Equal(.857m,snapshot.Calculated.RemovedTime);Assert.Equal("CORTE PARCIAL",snapshot.Calculated.Observation);}
 [Fact]public void CompletenessDependsOnCountEvenIfOmittedOperationHasZeroTime(){var request=Request(false);request.UsedTime=1.557m;request.PartialSelection=request.PartialSelection! with{Operations=[request.PartialSelection.Operations[0] with{StandardTime=1.557m}]};var snapshot=AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today);Assert.Equal("TIEMPO PARCIAL",snapshot.Calculated.TimeLabel);}
 [Fact]public void PersistsModeAndSectorInSnapshot(){var snapshot=AnalisisRbHistoryService.BuildSnapshot(Request(),DateTime.Today);var restored=System.Text.Json.JsonSerializer.Deserialize<AnalisisRbSnapshot>(System.Text.Json.JsonSerializer.Serialize(snapshot));Assert.True(restored!.SectorAnalysis!.IsComplete);Assert.Equal("CO",restored.SectorAnalysis.Sector);Assert.Equal(9,restored.SectorAnalysis.SelectedOperations);}
 [Theory][InlineData("flag")][InlineData("time")][InlineData("list")][InlineData("partialTime")][InlineData("sector")]public void RejectsInconsistentSectorContext(string mode){var request=Request(mode!="partialTime"&&mode!="sector");if(mode=="flag")request.SectorAnalysis=request.SectorAnalysis! with{SelectedOperations=1};if(mode=="time")request.UsedTime=1;if(mode=="list")request.PartialSelection=new("99863","0","CO","CORTE",1.557m,[new("01","CORTE","001","OP1","0","CORTAR",.7m)]);if(mode=="partialTime")request.UsedTime=.8m;if(mode=="sector")request.PartialSelection=request.PartialSelection! with{Sector="CS"};Assert.Throws<ArgumentException>(()=>AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today));}
}
